package com.ercopac.ercopac_tracker.ticketing.domain;
import com.ercopac.ercopac_tracker.user.AppUser; import jakarta.persistence.*; import java.time.Instant;
@Entity @Table(name="ticket_activities", indexes=@Index(name="idx_ticket_activity_ticket_created",columnList="ticket_id,created_at")) public class TicketActivity {
 @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="ticket_id",nullable=false) private Ticket ticket; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="actor_id") private AppUser actor;
 @Enumerated(EnumType.STRING) @Column(name="activity_type",nullable=false,length=32) private TicketActivityType activityType; @Column(name="previous_value",length=500) private String previousValue; @Column(name="new_value",length=500) private String newValue; @Column(nullable=false,length=1000) private String description; @Column(name="created_at",nullable=false,updatable=false) private Instant createdAt;
 @PrePersist void created(){createdAt=Instant.now();} public Long getId(){return id;} public Ticket getTicket(){return ticket;} public void setTicket(Ticket v){ticket=v;} public AppUser getActor(){return actor;} public void setActor(AppUser v){actor=v;} public TicketActivityType getActivityType(){return activityType;} public void setActivityType(TicketActivityType v){activityType=v;} public String getPreviousValue(){return previousValue;} public void setPreviousValue(String v){previousValue=v;} public String getNewValue(){return newValue;} public void setNewValue(String v){newValue=v;} public String getDescription(){return description;} public void setDescription(String v){description=v;} public Instant getCreatedAt(){return createdAt;}
}
